window.MEETING_ORIGINAL_HTML="<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>两辆车怎样走完一条路？</title><style id=\"itv-style\">/* Namespaced interactive film */\n.nv-film{--nv-ink:#182e2a;--nv-paper:#f3ebdd;--nv-red:#b44b36;border:1px solid #d8ccba!important;background:var(--nv-paper)!important;padding:24px!important;overflow:hidden;border-radius:14px;margin:22px 0}\n.nv-kicker{color:#577568;font-size:13px;letter-spacing:2px}.nv-film h2{color:var(--nv-ink);font-size:29px;margin:8px 0!important;border:0!important}.nv-lead{font-size:15px;color:#53675e;margin:8px 0 18px}\n.nv-player{background:#14241f;color:#fff;border-radius:14px;overflow:hidden;position:relative}.nv-player video{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;background:#14241f}.nv-controls{display:flex;gap:9px;align-items:center;flex-wrap:wrap;padding:12px 16px;background:#182e2a}.nv-film button{font:inherit;cursor:pointer;border:1px solid #b8c8ba;border-radius:7px;background:transparent;color:inherit;padding:7px 12px}.nv-controls button,.nv-question button{color:#fff}.nv-controls input[type=range]{flex:1;min-width:90px;accent-color:#d7b579}.nv-time{font-size:12px;font-variant-numeric:tabular-nums}.nv-question{background:#203b32;padding:20px;max-height:44vh;overflow:auto}.nv-question[hidden]{display:none}.nv-question h3{font-size:20px;margin:0 0 12px}.nv-field{display:inline-flex;flex-direction:column;gap:5px;width:calc(33% - 12px);min-width:180px;margin:0 12px 12px 0;font-size:14px}.nv-field input{background:#fff9ed;color:#182e2a;border:1px solid #d8ccba;border-radius:6px;padding:10px;font:inherit;width:100%;box-sizing:border-box}.nv-field input:focus{outline:3px solid #d7b579}.nv-actions{display:flex;gap:10px;flex-wrap:wrap}.nv-primary{background:#d6b37c!important;color:#14241f!important;border:0!important}.nv-feedback{line-height:1.7;font-size:14px;color:#ecd9b8}.nv-chapters{display:flex;gap:7px;flex-wrap:wrap;margin:15px 0}.nv-chapters button{color:#284b3c;font-size:13px}.nv-chapters button[aria-current=true]{background:#182e2a;color:#fff}.nv-chapters .nv-done:after{content:' ✓';color:#b44b36}.nv-status{font-size:14px;color:#53675e;min-height:22px}.nv-film details{border-top:1px solid #d8ccba;padding-top:12px;margin-top:12px;font-size:14px;line-height:1.8}.nv-film summary{cursor:pointer}.nv-film a{color:#7d392a}.nv-transcript{max-height:240px;overflow:auto;white-space:pre-line}.nv-sync{display:inline-flex;flex-direction:column;vertical-align:middle;margin:2px 4px;font-size:inherit}.nv-sync input{font:inherit;color:#182e2a;background:#fff9ed;border:0;border-bottom:2px solid #a77842;width:7.4em;max-width:150px;padding:4px;box-sizing:border-box}.nv-sync input[data-state=wrong]{border-bottom-color:#b44b36;color:#b44b36}.nv-sync small{font-size:11px;color:#8d5d27;display:none}.nv-sync:focus-within small,.nv-sync.nv-show-ref small{display:block}.nv-player:fullscreen{display:flex;flex-direction:column;overflow:auto;border-radius:0;width:100vw;height:100vh}.nv-player:fullscreen video{min-height:0;flex:1;height:auto;max-height:75vh}.nv-player:fullscreen .nv-question{max-height:42vh;flex-shrink:0}.nv-player:fullscreen .nv-controls{flex-shrink:0}.nv-player:fullscreen:has(.nv-question:not([hidden])) video{max-height:52vh}.nv-film :focus-visible{outline:3px solid #b44b36;outline-offset:3px}@media(max-width:700px){.nv-film{padding:12px!important}.nv-film h2{font-size:22px}.nv-field{width:100%;min-width:0}.nv-question{padding:14px;max-height:50vh}.nv-controls{gap:6px;padding:9px}.nv-film button{padding:7px 9px}.nv-player:fullscreen:has(.nv-question:not([hidden])) video{max-height:35vh}}\n.nv-screen{position:relative;min-height:0}.nv-caption{position:absolute;bottom:3%;left:8%;right:8%;text-align:center;pointer-events:none;color:#fff8e8;font-family:inherit;font-size:clamp(14px,1.55vw,28px);line-height:1.65;min-height:1.7em;text-shadow:0 2px 5px #000}.nv-caption span{background:rgba(20,36,31,.88);padding:.25em .6em;box-decoration-break:clone;-webkit-box-decoration-break:clone;border-radius:4px}.nv-player:fullscreen .nv-screen{display:flex;justify-content:center;flex:1;min-height:0;max-height:78vh}.nv-player:fullscreen video{height:100%;width:100%;max-height:none}.nv-player:fullscreen:has(.nv-question:not([hidden])) .nv-screen{max-height:52vh}.nv-player:fullscreen .nv-caption{font-size:26px}@media(max-width:700px){.nv-player:fullscreen:has(.nv-question:not([hidden])) .nv-screen{max-height:35vh}.nv-player:fullscreen .nv-caption{font-size:16px}}\n.nv-field textarea{font:inherit;box-sizing:border-box;width:100%;background:#fff9ed;color:#182e2a;padding:10px;border-radius:6px}.nv-field fieldset,.nv-field legend{padding:0}.nv-field input[type=radio]{width:auto;margin-right:8px}.itv-list{margin-top:22px;color:#182e2a}.nv-field{box-sizing:border-box}.nv-field legend{margin-bottom:8px}.itv-external{color:inherit;font:inherit;max-width:180px}fieldset.nv-field{border:1px solid #b8c8ba;padding:10px}\n.nv-lab{display:block;width:100%;aspect-ratio:16/9;border:1px solid #4e6b61;border-radius:10px;background:#1a1a2e;margin:0 0 14px}\n</style><style>body{margin:0 auto;max-width:1200px;padding:12px;font:18px/1.6 system-ui;background:#f8f5ef}</style><style>\n.nv-film{background:#faf5e8!important;border-radius:24px;padding:28px!important}.nv-kicker{font-size:15px}.nv-film h2{font-size:34px}.nv-lead{font-size:18px}.nv-field{width:100%;min-width:0;font-size:18px}.nv-question{max-height:49vh}.nv-question h3{font-size:25px}.nv-feedback{font-size:17px}.nv-field label{display:block;margin:.6em 0}.nv-actions button{min-height:44px}.itv-list-fields{display:grid;grid-template-columns:1fr 1fr;gap:22px}.itv-list .nv-field{margin:0}.nv-caption{font-size:clamp(14px,1.55vw,24px)}.nv-film :is(input,textarea){font-size:18px}.nv-controls{position:relative;z-index:2}.nv-player video{cursor:pointer}@media(max-width:700px){body{padding:4px!important}.nv-film{padding:12px!important}.nv-film h2{font-size:25px}.nv-lead{font-size:16px}.itv-list-fields{grid-template-columns:1fr}.nv-field{font-size:16px}.nv-controls .nv-seek{flex-basis:100%}.nv-question{max-height:55vh}.nv-caption{position:static;left:auto;right:auto;bottom:auto;font-size:14px;min-height:3.4em;padding:8px 10px;box-sizing:border-box;background:#182e2a}.nv-caption span{padding:0;background:transparent}.nv-player:fullscreen .nv-screen{flex-direction:column}.nv-player:fullscreen video{min-height:0;height:auto;max-height:65vh}.nv-player:fullscreen:has(.nv-question:not([hidden])) video{max-height:28vh}.nv-player:fullscreen .nv-caption{font-size:14px;flex-shrink:0}}\n</style></head><body><!--ITV_MODULE_START--><section class=\"nv-film\" id=\"itv-film\"><div class=\"nv-kicker\">第三单元 · 物流中的数学</div><h2>两辆车怎样走完一条路？</h2><p class=\"nv-lead\">跟着同一个时钟，看看两辆车走过的路和中间空隙怎样变化。</p><div class=\"nv-player\"><div class=\"nv-screen\"><video tabindex=\"0\" playsinline preload=\"metadata\" poster=\"data:image/png;base64,\" src=\"data:video/mp4;base64,\"></video><div class=\"nv-caption\" aria-hidden=\"true\"></div></div><div class=\"nv-controls\"><button class=\"nv-play\" type=\"button\">播放</button><span class=\"nv-time\">0:00</span><input class=\"nv-seek\" type=\"range\" min=\"0\" max=\"1\" value=\"0\" step=\"0.1\" aria-label=\"播放进度\"><button class=\"nv-subtitles\" type=\"button\" aria-pressed=\"true\">隐藏字幕</button><button class=\"nv-mute\" type=\"button\">静音</button><button class=\"nv-fullscreen\" type=\"button\">全屏观看</button></div><section class=\"nv-question\" hidden aria-label=\"学习活动\"><h3>知识整理</h3><form><div class=\"nv-fields\"></div><p class=\"nv-feedback\" aria-live=\"polite\"></p><div class=\"nv-actions\"><button type=\"submit\" class=\"nv-primary\">核对记录</button><button type=\"button\" class=\"nv-hint\">需要一点提示</button><button type=\"button\" class=\"nv-continue nv-primary\" hidden>继续学习</button><button type=\"button\" class=\"nv-replay\">重看本段</button><button type=\"button\" class=\"nv-skip\">先跳过</button></div></form></section></div><div class=\"nv-chapters\" aria-label=\"讲解章节\"></div><p class=\"nv-status\" aria-live=\"polite\"></p><div class=\"nv-actions\"><button type=\"button\" class=\"nv-to-list\">查看我的思考</button><button type=\"button\" class=\"nv-reset\">重置本节</button></div><details><summary>阅读讲解内容</summary><div class=\"nv-transcript\"></div></details><details class=\"nv-review\"><summary>回顾我的思考</summary><section class=\"itv-list\"><h3>我的思考</h3><div class=\"itv-list-fields\"></div></section></section>\n<!--ITV_MODULE_END--><script id=\"itv-data\" type=\"application/json\">{\"lesson_id\": \"u03-meeting-meaning-v1\", \"title\": \"两辆车怎样走完一条路？\", \"scenes\": [{\"id\": \"start\", \"title\": \"先想一想\", \"start\": 0, \"end\": 31.966667, \"narration\": \"小林和小禾在整理配送路线。两辆车从道路两头开过来，它们各自走过的路，怎样合成两城之间的路程呢？\\n小货车从海城出发，每小时行驶六十四千米。大货车从东城出发，每小时行驶七十二千米。两辆车同时出发，相向而行，四小时后在仓储中心相遇。海城和东城之间的路程是多少千米？你可以先想一想自己的方法。\", \"activity_title\": \"先想一想\", \"instruction\": \"先试着回答。需要帮助时，可以看提示或重看。\", \"fields\": [{\"id\": \"start-response\", \"type\": \"observe\", \"prompt\": \"海城和东城之间的路程怎样求？写算式、说想法或指着图说都可以。\", \"hints\": [\"先找两辆车各自的速度，以及它们行驶了多长时间。\", \"可以先想一辆车走了多少路，再想怎样合起来。\"]}]}, {\"id\": \"gap\", \"title\": \"观察同一个小时\", \"start\": 31.966667, \"end\": 51.7, \"narration\": \"先只看出发后的第一个小时。时钟走了一小时，两辆车也都行驶了一小时。小货车走了六十四千米，大货车走了七十二千米。中间还没有走完的这一段，是两辆车之间的空隙。空隙比出发时缩短了多少千米？\", \"activity_title\": \"观察同一个小时\", \"instruction\": \"先试着回答。需要帮助时，可以看提示或重看。\", \"fields\": [{\"id\": \"gap-response\", \"type\": \"fill\", \"prompt\": \"一小时后，两车之间的空隙比出发时缩短了多少千米？\", \"answers\": [\"136\", \"136千米\", \"一百三十六\", \"一百三十六千米\"], \"hints\": [\"这同一个小时内，小货车走了64千米，大货车走了72千米。\", \"这两段原来都在两车之间的空隙里，现在都被走过了。\", \"空隙从两头一起缩短：64＋72＝136（千米）。\"]}]}, {\"id\": \"meaning\", \"title\": \"说清这个数\", \"start\": 51.7, \"end\": 95.366667, \"narration\": \"看，小货车从左边走过六十四千米，大货车从右边走过七十二千米。这两段原来都在空隙里，现在都被走过了。所以，一小时里，空隙一共缩短六十四加七十二，等于一百三十六千米。把两个速度相加，是在看同一小时里，两辆车合起来让空隙缩短得有多快。\\n小货车自己的速度仍然是六十四千米每小时，大货车仍然是七十二千米每小时。一百三十六千米每小时，表示两车相向行驶时，空隙每小时缩短一百三十六千米。它不是其中任何一辆车自己的速度。\", \"activity_title\": \"说清这个数\", \"instruction\": \"先试着回答。需要帮助时，可以看提示或重看。\", \"fields\": [{\"id\": \"meaning-response\", \"type\": \"choice\", \"prompt\": \"136千米/时描述的是什么？\", \"options\": [{\"id\": \"truck\", \"label\": \"小货车自己的速度\"}, {\"id\": \"gap\", \"label\": \"两车相向行驶时，空隙每小时缩短的距离\"}, {\"id\": \"each\", \"label\": \"每一辆车自己的速度\"}], \"answer\": \"gap\", \"hints\": [\"小货车自己的速度是64千米/时，大货车是72千米/时。\", \"把两辆车在同一小时内走过的路合起来，想一想空隙怎样变化。\", \"136千米/时表示两车相向行驶时，空隙每小时缩短136千米。\"]}]}, {\"id\": \"time\", \"title\": \"检查时间条件\", \"start\": 95.366667, \"end\": 156.7, \"narration\": \"再让同一个时钟走到四小时。每一小时，两辆车合起来走一百三十六千米。四个小时，两车相遇，空隙正好变成零。所以，两城之间的路程，就是一百三十六乘四，等于五百四十四千米。注意，相遇不一定在路的正中间，因为两辆车的速度不同。\\n也可以按车辆来算。小货车四小时走二百五十六千米，大货车四小时走二百八十八千米，加起来也是五百四十四千米。一个方法先分车辆，一个方法先分共同的时间。它们算的是同一条路。\\n如果一辆车行驶四小时，另一辆只行驶三小时，就要分别算出它们各自的路程，再相加。不能把两个速度加起来，就直接乘四，算成两辆车都行驶四小时。先弄清每辆车走了多长时间，再决定怎样组合路程。\", \"activity_title\": \"检查时间条件\", \"instruction\": \"先试着回答。需要帮助时，可以看提示或重看。\", \"fields\": [{\"id\": \"time-response\", \"type\": \"observe\", \"prompt\": \"一辆车走4小时，另一辆只走3小时。为什么不能把两个速度相加后直接乘4？\", \"hints\": [\"式子里的时间，应当对应实际走路的每一辆车。\", \"如果把两个速度相加后乘4，就把两辆车都按走4小时计算了。\", \"应分别求各自实际时间内的路程，再相加。\"]}]}], \"captions\": [{\"start\": 0.1, \"end\": 3.15526, \"text\": \"小林和小禾在整理配送路线。\"}, {\"start\": 3.10526, \"end\": 7.18498, \"text\": \"两辆车从道路两头开过来，它们各自走过的路，\"}, {\"start\": 7.18498, \"end\": 9.71053, \"text\": \"怎样合成两城之间的路程呢？\"}, {\"start\": 10.5, \"end\": 14.95, \"text\": \"小货车从海城出发，每小时行驶六十四千米。\"}, {\"start\": 14.9, \"end\": 19.28158, \"text\": \"大货车从东城出发，每小时行驶七十二千米。\"}, {\"start\": 19.28158, \"end\": 24.9, \"text\": \"两辆车同时出发，相向而行，四小时后在仓储中心相遇。\"}, {\"start\": 24.9, \"end\": 28.61053, \"text\": \"海城和东城之间的路程是多少千米？\"}, {\"start\": 28.61053, \"end\": 31.28158, \"text\": \"你可以先想一想自己的方法。\"}, {\"start\": 32.06667, \"end\": 34.85877, \"text\": \"先只看出发后的第一个小时。\"}, {\"start\": 34.80877, \"end\": 38.83509, \"text\": \"时钟走了一小时，两辆车也都行驶了一小时。\"}, {\"start\": 38.83509, \"end\": 43.32193, \"text\": \"小货车走了六十四千米，大货车走了七十二千米。\"}, {\"start\": 43.32193, \"end\": 47.65088, \"text\": \"中间还没有走完的这一段，是两辆车之间的空隙。\"}, {\"start\": 47.65088, \"end\": 51.00614, \"text\": \"空隙比出发时缩短了多少千米？\"}, {\"start\": 51.8, \"end\": 58.26316, \"text\": \"看，小货车从左边走过六十四千米，大货车从右边走过七十二千米。\"}, {\"start\": 58.21316, \"end\": 62.12105, \"text\": \"这两段原来都在空隙里，现在都被走过了。\"}, {\"start\": 62.12105, \"end\": 66.68931, \"text\": \"所以，一小时里，空隙一共缩短六十四加七十二，\"}, {\"start\": 66.68931, \"end\": 68.76579, \"text\": \"等于一百三十六千米。\"}, {\"start\": 68.76579, \"end\": 72.42608, \"text\": \"把两个速度相加，是在看同一小时里，\"}, {\"start\": 72.42608, \"end\": 75.87105, \"text\": \"两辆车合起来让空隙缩短得有多快。\"}, {\"start\": 76.66667, \"end\": 80.60802, \"text\": \"小货车自己的速度仍然是六十四千米每小时，\"}, {\"start\": 80.60802, \"end\": 83.56404, \"text\": \"大货车仍然是七十二千米每小时。\"}, {\"start\": 83.51404, \"end\": 88.07325, \"text\": \"一百三十六千米每小时，表示两车相向行驶时，\"}, {\"start\": 88.07325, \"end\": 91.32982, \"text\": \"空隙每小时缩短一百三十六千米。\"}, {\"start\": 91.32982, \"end\": 94.69825, \"text\": \"它不是其中任何一辆车自己的速度。\"}, {\"start\": 95.46667, \"end\": 98.45614, \"text\": \"再让同一个时钟走到四小时。\"}, {\"start\": 98.40614, \"end\": 102.73509, \"text\": \"每一小时，两辆车合起来走一百三十六千米。\"}, {\"start\": 102.73509, \"end\": 107.07719, \"text\": \"四个小时，两车相遇，空隙正好变成零。\"}, {\"start\": 107.07719, \"end\": 111.37346, \"text\": \"所以，两城之间的路程，就是一百三十六乘四，\"}, {\"start\": 111.37346, \"end\": 113.4193, \"text\": \"等于五百四十四千米。\"}, {\"start\": 113.4193, \"end\": 118.5114, \"text\": \"注意，相遇不一定在路的正中间，因为两辆车的速度不同。\"}, {\"start\": 119.3, \"end\": 121.30263, \"text\": \"也可以按车辆来算。\"}, {\"start\": 121.25263, \"end\": 127.05435, \"text\": \"小货车四小时走二百五十六千米，大货车四小时走二百八十八千米，\"}, {\"start\": 127.05435, \"end\": 129.56842, \"text\": \"加起来也是五百四十四千米。\"}, {\"start\": 129.56842, \"end\": 134.06842, \"text\": \"一个方法先分车辆，一个方法先分共同的时间。\"}, {\"start\": 134.06842, \"end\": 136.47632, \"text\": \"它们算的是同一条路。\"}, {\"start\": 137.23333, \"end\": 141.47868, \"text\": \"如果一辆车行驶四小时，另一辆只行驶三小时，\"}, {\"start\": 141.47868, \"end\": 145.11754, \"text\": \"就要分别算出它们各自的路程，再相加。\"}, {\"start\": 145.06754, \"end\": 151.21228, \"text\": \"不能把两个速度加起来，就直接乘四，算成两辆车都行驶四小时。\"}, {\"start\": 151.21228, \"end\": 156.02741, \"text\": \"先弄清每辆车走了多长时间，再决定怎样组合路程。\"}]}</script><script id=\"itv-runtime\">(()=>{'use strict';\nconst film=document.getElementById('itv-film');if(!film)return;\nconst cfg=JSON.parse(document.getElementById('itv-data').textContent),scenes=cfg.scenes,all=scenes.flatMap(s=>s.fields),byid=new Map(all.map(f=>[f.id,f]));\nconst root=film.querySelector('.nv-player'),v=root.querySelector('video'),panel=root.querySelector('.nv-question'),form=panel.querySelector('form'),box=panel.querySelector('.nv-fields'),fb=panel.querySelector('.nv-feedback'),status=film.querySelector('.nv-status'),play=root.querySelector('.nv-play'),seekbar=root.querySelector('.nv-seek');\nlet state={answers:{},visited:{},position:0},storage=true,active=0,waiting=null,revisit=false,internal=false,lastSave=0,lab=null,hintStep=0,controlInstance=0;\nconst key='itv:'+cfg.lesson_id,escape=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),norm=s=>String(s??'').normalize('NFKC').trim().replace(/\\s+/g,' '),fmt=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');\n\nfunction save(){if(v.readyState)state.position=v.currentTime;}\nfunction correct(f,value){return f.type==='observe'?null:f.type==='choice'?value===f.answer:f.answers.some(a=>norm(a)===norm(value));}\nfunction update(){status.textContent='本次作答仅在当前页面保留。'+'已回顾 '+Object.keys(state.visited).filter(k=>state.visited[k]).length+' / '+scenes.length+' 段，记录 '+all.filter(f=>state.answers[f.id]).length+' / '+all.length+' 项。';film.querySelectorAll('[data-scene]').forEach((b,i)=>{b.classList.toggle('nv-done',!!state.visited[scenes[i].id]);b.setAttribute('aria-current',String(active===i));});}\nfunction sync(id,value){const f=byid.get(id);if(!f)return;value=String(value).slice(0,f.type==='observe'?1000:160);state.answers[id]=value;document.querySelectorAll('[data-itv-field]').forEach(el=>{if(el.dataset.itvField!==id)return;if(el.type==='radio')el.checked=el.value===value;else if(el!==document.activeElement)el.value=value;el.dataset.state=!value?'empty':correct(f,value)===false?'wrong':correct(f,value)===true?'correct':'recorded';});save();update();}\nfunction control(f,value=''){const group=++controlInstance;const id=escape(f.id),label=escape(f.prompt);if(f.type==='choice')return '<fieldset class=\"nv-field\"><legend>'+label+'</legend>'+f.options.map(o=>'<label><input type=\"radio\" name=\"itv-'+id+'-'+group+'\" data-itv-field=\"'+id+'\" value=\"'+escape(o.id)+'\" '+(value===o.id?'checked':'')+'>'+escape(o.label)+'</label>').join('')+'</fieldset>';return '<label class=\"nv-field\">'+label+(f.type==='observe'?'<textarea rows=\"3\" maxlength=\"1000\"':'<input maxlength=\"160\"')+' data-itv-field=\"'+id+'\" '+(f.type==='observe'?'>'+escape(value)+'</textarea>':'value=\"'+escape(value)+'\" placeholder=\"填写关键词\">')+'</label>';}\nfunction unmountLab(){if(lab){lab.remove();lab=null;}box.hidden=false;}\nfunction mountLab(i){const f=scenes[i].fields.find(x=>typeof x.lab_srcdoc==='string'&&x.lab_srcdoc.trim());if(!f)return;const frame=document.createElement('iframe');frame.className='nv-lab';frame.title=f.prompt;frame.srcdoc=f.lab_srcdoc;frame.setAttribute('sandbox','allow-scripts');box.hidden=true;box.before(frame);lab=frame;}\nfunction question(i){hintStep=0;v.pause();active=i;waiting=i;revisit=false;panel.hidden=false;panel.querySelector('h3').textContent=scenes[i].activity_title||'知识整理';unmountLab();box.innerHTML=scenes[i].fields.map(f=>control(f,state.answers[f.id]||'')).join('');mountLab(i);fb.textContent=scenes[i].instruction||'根据刚才的讲解，完成记录。';form.querySelector('[type=submit]').hidden=false;panel.querySelector('.nv-continue').hidden=true;panel.querySelector('.nv-skip').textContent='先跳过';update();box.querySelector('input,textarea')?.focus({preventScroll:true});}\nfunction finish(){v.pause();waiting=null;unmountLab();panel.hidden=false;box.innerHTML='';panel.querySelector('h3').textContent='这一段已看完';fb.textContent='可以回看画面，再完善自己的想法。';form.querySelector('[type=submit]').hidden=true;panel.querySelector('.nv-continue').hidden=true;panel.querySelector('.nv-skip').textContent='收起';save();update();}\nasync function resume(){if(waiting!==null)return;unmountLab();panel.hidden=true;try{await v.play();}catch(e){status.textContent='请点击播放；若无法启动，可使用 Chrome 或 Edge 打开。';}}\nfunction seek(t,guard=true){v.pause();t=Math.max(0,Math.min(t,v.duration||scenes.at(-1).end));if(guard&&t>v.currentTime){const i=scenes.findIndex(s=>!state.visited[s.id]&&s.end>=v.currentTime-.15&&s.end<=t);if(i>=0){internal=true;v.currentTime=Math.min(scenes[i].end,v.duration||scenes[i].end);setTimeout(()=>internal=false,150);question(i);return;}}internal=true;waiting=null;unmountLab();v.currentTime=t;active=scenes.findIndex(s=>t<s.end);if(active<0)active=scenes.length-1;panel.hidden=true;setTimeout(()=>internal=false,150);save();update();}\nfunction next(){if(waiting===null){panel.hidden=true;return;}const i=waiting;state.visited[scenes[i].id]=true;waiting=null;if(i===scenes.length-1){save();update();finish();return;}active=i+1;revisit=false;save();update();resume();}\ndocument.addEventListener('input',e=>{const el=e.target;if(el.dataset.itvField&&(el.type!=='radio'||el.checked))sync(el.dataset.itvField,el.value);});\nwindow.addEventListener('message',e=>{const d=e.data;if(!lab||e.source!==lab.contentWindow||!d||d.type!=='lab-field'||!byid.has(d.id))return;sync(d.id,d.value??'');});\nform.onsubmit=e=>{e.preventDefault();if(waiting===null)return;fb.textContent=scenes[waiting].fields.map(f=>{const value=state.answers[f.id]||'';if(f.type==='observe')return f.prompt+'：'+(value?'已记录。':'尚未记录。');const answer=f.type==='choice'?f.options.find(o=>o.id===f.answer).label:f.answers[0];return !value?'还没有填写，可以先写下自己的想法。':correct(f,value)?'这一项与图中的数量关系一致。':(f.hints?.[0]||'请回到图中，检查这个数对应的对象和时间。');}).join(' ');panel.querySelector('.nv-continue').hidden=false;};\npanel.querySelector('.nv-hint').onclick=()=>{if(waiting===null)return;const hints=scenes[waiting].fields[0].hints||[];if(hints.length){fb.textContent=hints[Math.min(hintStep,hints.length-1)];hintStep++;state.hints=state.hints||{};state.hints[scenes[waiting].id]=hintStep;save();}};panel.querySelector('.nv-continue').onclick=next;panel.querySelector('.nv-skip').onclick=next;panel.querySelector('.nv-replay').onclick=()=>{const i=waiting??active;seek(scenes[i].start,false);revisit=true;resume();};play.onclick=()=>{if(waiting===null)v.paused?resume():v.pause();};v.onclick=()=>play.click();\nv.addEventListener('play',()=>{if(waiting!==null)v.pause();else play.textContent='暂停';});v.addEventListener('pause',()=>{play.textContent='播放';save();});\nv.addEventListener('timeupdate',()=>{root.querySelector('.nv-time').textContent=fmt(v.currentTime)+' / '+fmt(v.duration||0);seekbar.value=v.currentTime;if(!internal&&waiting===null&&!v.paused){const s=scenes[active];if(v.currentTime>=s.end-.1&&(!state.visited[s.id]||revisit))question(active);else{const a=scenes.findIndex(s=>v.currentTime<s.end);if(a>=0)active=a;}}if(Date.now()-lastSave>2500){lastSave=Date.now();save();}});\nv.addEventListener('ended',()=>{if(waiting!==null)return;const i=scenes.findIndex(s=>!state.visited[s.id]);i>=0?question(i):finish();});v.addEventListener('loadedmetadata',()=>{seekbar.max=v.duration;seek(Math.min(state.position,Math.max(0,v.duration-.2)),false);});v.addEventListener('error',()=>status.textContent='视频未能加载，请重新打开或使用其他浏览器。');seekbar.onchange=()=>seek(Number(seekbar.value));\nroot.querySelector('.nv-mute').onclick=e=>{v.muted=!v.muted;e.target.textContent=v.muted?'开启声音':'静音';};root.querySelector('.nv-fullscreen').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await root.requestFullscreen();}catch(e){status.textContent='当前浏览器无法进入全屏。';}};\nlet show=true;const captions=cfg.captions||[];function paint(){const cue=captions.find(c=>v.currentTime>=c.start&&v.currentTime<c.end),b=root.querySelector('.nv-caption');b.replaceChildren();if(show&&cue){const span=document.createElement('span');span.textContent=cue.text;b.append(span);}}v.addEventListener('timeupdate',paint);v.addEventListener('seeked',paint);root.querySelector('.nv-subtitles').onclick=e=>{show=!show;e.target.textContent=show?'隐藏字幕':'显示字幕';e.target.setAttribute('aria-pressed',String(show));paint();};\nfilm.querySelector('.nv-chapters').innerHTML=scenes.map((s,i)=>'<button type=\"button\" data-scene=\"'+i+'\">'+escape(s.title)+'</button>').join('');film.querySelector('.nv-chapters').onclick=e=>{const b=e.target.closest('[data-scene]');if(b){seek(scenes[Number(b.dataset.scene)].start,false);revisit=true;resume();}};\nfilm.querySelector('.nv-reset').onclick=()=>{v.pause();state={answers:{},visited:{},position:0};document.querySelectorAll('[data-itv-field]').forEach(el=>{if(el.type==='radio')el.checked=false;else el.value='';delete el.dataset.state;});revisit=false;seek(0,false);save();update();};film.querySelector('.nv-to-list').onclick=()=>{v.pause();film.querySelector('.nv-review').open=true;film.querySelector('.itv-list').scrollIntoView({behavior:'smooth'});};film.querySelector('.nv-transcript').textContent=scenes.map(s=>s.title+'\\n'+(s.narration||'')).join('\\n\\n');film.querySelector('.itv-list-fields').innerHTML=all.map(f=>control(f,state.answers[f.id]||'')).join('');\nroot.addEventListener('keydown',e=>{e.stopPropagation();if(e.target.matches('input,textarea,select'))return;if(e.key===' '&&e.target===v){e.preventDefault();play.click();}});Object.entries(state.answers).forEach(([id,value])=>sync(id,value));update();\n})();\n</script></body></html>";
